// Optimized for:
// - Memory locality: all matrix accesses follow the row‑major layout of A.
// - Reduced redundant loads: row/element invariants hoisted out of inner loops.
// - Still expressed purely via Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	#pragma scop

