	traverser(A, w, x_j).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state(); // fixed 'i'

		// Accumulator for this row i
		num_t w_i = w[state_i];

		// Walk across columns j in row i; this is contiguous in memory
		trav_i.for_each([&](auto state) {
			w_i += alpha * A[state] * x_j[state];
		});

		// Write back the accumulated value once per row
		w[state_i] = w_i;
	});

	#pragma endscop
