			// state has 'j' (fixed) and 'i' (varying)
			// x only depends on 'i', extra 'j' in state is ignored
			x[state] = x[state] + factor * A_T[state];
		});
	});

	// --------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i];
	// Simple element-wise vector addition over dimension 'i'.
	// --------------------------------------------------------------------
	traverser(x, z).for_each([&](auto state) {
		x[state] = x[state] + z[state];
	});

	// --------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i][j] * x[j];
	//
	// This is a matrix-vector product using updated x.
	// We want 'j' as the inner (contiguous) dimension of A (row-major),
	// so we traverse A row-by-row as in step 1.
	//
	// To index x by 'j' we build a view x_j where x_j[j] == x[j].
	// For each row i we:
	//   - cache w[i] in a register (wi),
	//   - accumulate wi across all j,
	//   - write wi back to w[i] once per row.
	// This reduces memory traffic on w and gives the compiler a clear
	// reduction pattern over 'j'.
	// --------------------------------------------------------------------
	auto x_j = x ^ noarr::rename<'i', 'j'>(); // view of x indexed by 'j'

	traverser(A, w, x_j).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state(); // fixed 'i'

		// Cache current w[i] in a register
		num_t wi = w[state_i];

		trav_i.for_each([&](auto state) {
			// state has 'i' (fixed) and 'j' (varying)
			wi += alpha * A[state] * x_j[state];
		});

		// Write back accumulated value
		w[state_i] = wi;
	});

